import { computed } from "vue";
function useHorizontalLayoutMenu({
  menus,
  activeKey,
  expandedKeys
}) {
  const layout = computed(() => {
    return {
      verticalMenuProps: {},
      verticalExtraMenuProps: {},
      horizontalMenuProps: {
        mode: "horizontal",
        collapsed: false,
        responsive: true,
        options: menus.value,
        value: activeKey.value,
        expandedKeys: expandedKeys.value,
        onUpdateValue: (key) => {
          activeKey.value = key;
        },
        onUpdateExpandedKeys: (keys) => {
          expandedKeys.value = keys;
        }
      }
    };
  });
  return {
    layout
  };
}
export {
  useHorizontalLayoutMenu
};
